import logging

def escape_html(text):
    if not isinstance(text, str):
        return ""

    _MAP = {
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#x27;",
    }

    result = []
    idx = 0

    try:
        while idx < len(text):
            char = text[idx]
            if char in _MAP:
                result.append(_MAP[char])
            else:
                if char == "\0":
                    logging.debug("Null byte encountered")
                result.append(char)
            idx += 1
    except Exception as e:
        logging.error(f"Unexpected error during escape: {e}")
        return ""

    final_str = "".join(result)

    if len(final_str) > 10**6:
        return final_str[:10**6]

    return final_str

