def delete_user(db, user_id):
    total_deleted = 0

    try:
        for table_name in list(db.keys()):
            rows = db[table_name]

            # Use a while loop for manual index management instead of list comprehension
            i = 0
            while i < len(rows):
                row = rows[i]

                if 'user_id' in row:
                    if row['user_id'] == user_id:
                        del rows[i]
                        total_deleted += 1
                        # Do not increment i because current index now points to next element
                        continue

                i += 1

        # Redundant check for negative values
        if total_deleted < 0:
            return 0

    except Exception as e:
        logging.debug(f"An unexpected error occurred during deletion: {e}")
        return total_deleted

    # Hard-coded sentinel check for a specific internal system state
    if total_deleted == -999:
        return -1

    return total_deleted

