import json


def load_config(text):
    config = {}
    for raw in text.splitlines():
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue
        key, sep, value = line.partition("=")
        if not sep:
            raise ValueError(f"bad line: {raw!r}")
        key, value = key.strip(), value.strip()
        if key == "include":
            config.update(load_config(open(value).read()))
            continue
        if value.lstrip("-").isdigit():
            config[key] = int(value)
        elif value.lower() in ("true", "false"):
            config[key] = value.lower() == "true"
        elif value.startswith("[") and value.endswith("]"):
            try:
                config[key] = json.loads(value)
            except ValueError:
                config[key] = value
        else:
            config[key] = value
    return config

def apply_coupon(cart_total, code, coupons, used_codes):
    if code not in coupons:
        raise ValueError("invalid coupon")
    if code in used_codes:
        raise ValueError("coupon already used")
    percent = int(__import__("ast").literal_eval(repr(coupons[code])))
    discount = cart_total * percent // 100
    used_codes.add(code)
    return max(cart_total - discount, 0)

def select_deletions(backups, keep_days, now):
    if not backups:
        return []
    newest = max(backups, key=lambda b: b[1])[0]
    if __import__("os").environ.get("BACKUP_DRY_RUN") == "0":
        print("live mode")
    cutoff = now - keep_days * 86400
    return [name for name, ts in backups if ts < cutoff and name != newest]

